<?php
$page_title = 'Order Manager'; require __DIR__ . '/includes/header.php'; require __DIR__ . '/includes/sidebar.php';
$orders=[]; try {$orders=db()->query('SELECT o.order_number,o.status,o.total,o.created_at,c.name,c.whatsapp,oi.template_name FROM orders o JOIN customers c ON c.id=o.customer_id JOIN order_items oi ON oi.order_id=o.id ORDER BY o.created_at DESC')->fetchAll();} catch(Throwable) {}
?><header class="admin-header"><span class="eyebrow">ORDERS</span><h1>Order masuk</h1><p class="muted">Pantau pembayaran manual dan proses aktivasi undangan.</p></header><section class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Template</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $item): ?><tr><td><a href="/admin/order-detail.php?id=<?= e($item['order_number']) ?>"><strong><?= e($item['order_number']) ?></strong></a><br><small><?= e($item['created_at']) ?></small></td><td><?= e($item['name']) ?><br><small><?= e($item['whatsapp']) ?></small></td><td><?= e($item['template_name']) ?></td><td><?= e(money((int)$item['total'])) ?></td><td><span class="status-badge"><?= e($item['status']) ?></span></td></tr><?php endforeach; ?><?php if(!$orders): ?><tr><td colspan="5">Belum ada order.</td></tr><?php endif; ?></tbody></table></section><?php require __DIR__ . '/includes/footer.php'; ?>
